import{c as n,Q as t,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/DataCache%E5%86%85%E5%AD%98%E5%B1%82%E6%AC%A1%E7%A4%BA%E6%84%8F%E5%9B%BE.C5dXLgE4.png",A=JSON.parse('{"title":"DataCacheCleanAndInvalid","description":"","frontmatter":{},"headers":[{"level":1,"title":"DataCacheCleanAndInvalid","slug":"datacachecleanandinvalid"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/缓存控制/DataCacheCleanAndInvalid.md","filePath":"api/SIMD-API/基础API/缓存控制/DataCacheCleanAndInvalid.md"}'),d={name:"api/SIMD-API/基础API/缓存控制/DataCacheCleanAndInvalid.md"};function i(p,a,c,o,r,C){return t(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="datacachecleanandinvalid" tabindex="-1">DataCacheCleanAndInvalid <a class="header-anchor" href="#datacachecleanandinvalid" aria-label="Permalink to &quot;DataCacheCleanAndInvalid&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持（支持配置dcciDst的原型）</th><th>是否支持（不支持配置dcciDst的原型）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>在AI Core内部，Scalar单元和DMA单元都可能对Global Memory进行访问。</p><p><strong>图 1</strong> DataCache内存层次示意图<br><img src="'+l+`" alt="" title="DataCache内存层次示意图"></p><p>如上图所示：</p><ul><li>DMA搬运单元读写Global Memory，数据通过DataCopy等接口在UB等Local Memory和Global Memory间交互，没有Cache一致性问题；</li><li>Scalar单元访问Global Memory，首先会访问每个核内的Data Cache，因此存在Data Cache与Global Memory的Cache一致性问题。</li></ul><p>该接口用来刷新Cache，保证Cache的一致性，使用场景如下：</p><ul><li><p>读取Global Memory的数据，但该数据可能在外部被其余核修改，此时需要使用DataCacheCleanAndInvalid接口，直接访问Global Memory，获取最新数据；</p></li><li><p>用户通过Scalar单元写Global Memory的数据，希望立刻写出，也需要使用DataCacheCleanAndInvalid接口。</p></li><li><p>针对Ascend 950PR/Ascend 950DT，原子操作过程中，如果希望改变后续数据的饱和模式，需要先使用DataCacheCleanAndInvalid接口将Cache Line中现存的数据立刻写出，再调用<a href="./../系统变量访问/SetCtrlSpr(ISASI).html">SetCtrlSpr</a>设置后续数据的饱和模式。</p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>支持通过配置dcciDst确保Data Cache与GM存储的一致性</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, CacheLine entireType, DcciDst dcciDst&gt;</span></span>
<span class="line"><span>__aicore__ inline void DataCacheCleanAndInvalid(const GlobalTensor&lt;T&gt;&amp; dst)</span></span></code></pre></div></li><li><p>支持通过配置dcciDst确保Data Cache与Local Memory存储的一致性</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, CacheLine entireType, DcciDst dcciDst&gt;</span></span>
<span class="line"><span>__aicore__ inline void DataCacheCleanAndInvalid(const LocalTensor&lt;T&gt;&amp; dst)</span></span></code></pre></div></li><li><p>不支持配置dcciDst，仅支持保证Data Cache与GM的一致性</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, CacheLine entireType&gt;</span></span>
<span class="line"><span>__aicore__ inline void DataCacheCleanAndInvalid(const GlobalTensor&lt;T&gt;&amp; dst)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst的数据类型。</td></tr><tr><td>entireType</td><td>指令操作的模式： SINGLE_CACHE_LINE：只刷新传入地址所在的Cache Line，注意如果该地址非64B对齐，只会操作传入地址到64B对齐的部分。 ENTIRE_DATA_CACHE：此时传入的地址无效，核内会刷新整个Data Cache，但是耗时较大，性能敏感的场景慎用。</td></tr><tr><td>dcciDst</td><td>表示使用该接口来保证Data Cache与哪一种存储保持一致性，类型为DcciDst枚举类。 CACHELINE_ALL：与CACHELINE_OUT效果一致。CACHELINE_UB：表示通过该接口来保证Data Cache与UB的一致性。CACHELINE_OUT：表示通过该接口来保证Data Cache与Global Memory的一致性。CACHELINE_ATOMIC：Ascend 950PR/Ascend 950DT，原子操作过程中保证Data Cache和Global Memory的一致性。Atlas A3 训练系列产品/Atlas A3 推理系列产品，预留参数，暂未支持。Atlas A2 训练系列产品/Atlas A2 推理系列产品，预留参数，暂未支持。Atlas 200I/500 A2 推理产品，预留参数，暂未支持。Atlas 推理系列产品AI Core，预留参数，暂未支持。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输入</td><td>需要刷新Cache的Tensor。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 示例1：SINGLE_CACHE_LINE 模式，假设mmAddr_为0x40（64B对齐）</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;uint64_t&gt; global;</span></span>
<span class="line"><span>global.SetGlobalBuffer((__gm__ uint64_t*)mmAddr_ + AscendC::GetBlockIdx() * 1024);</span></span>
<span class="line"><span>for( int i = 0; i &lt; 8; i++) {</span></span>
<span class="line"><span>   global.SetValue(i, AscendC::GetBlockIdx());</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 由于首地址64B对齐，调用DataCacheCleanAndInvalid指令后，会立刻刷新前8个数</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;uint64_t, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT&gt;(global);</span></span>
<span class="line"><span>// 示例2：SINGLE_CACHE_LINE 模式，假设mmAddr_为0x20（非64B对齐）</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;uint64_t&gt; global;</span></span>
<span class="line"><span>global.SetGlobalBuffer((__gm__ uint64_t*)mmAddr_ + AscendC::GetBlockIdx() * 1024);</span></span>
<span class="line"><span>for( int i = 0; i &lt; 8; i++) {</span></span>
<span class="line"><span>   global.SetValue(i, AscendC::GetBlockIdx());</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 由于首地址非64B对齐，调用1条指令，只会刷新起始地址至64B字节对齐的部分，即前4个数</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;uint64_t, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT&gt;(global);</span></span>
<span class="line"><span>// 需要再次调用DataCacheCleanAndInvalid指令，刷新后4个数</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;uint64_t, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT&gt;(global[4]);</span></span>
<span class="line"><span>// 示例3：SINGLE_CACHE_LINE 模式，假设mmAddr_为0x40（64B对齐），多核处理场景（本样例仅做示例说明，便于开发者理解使用限制，非正常使用样例）</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;uint64_t&gt; global;</span></span>
<span class="line"><span>global.SetGlobalBuffer((__gm__ uint64_t*)mmAddr_);</span></span>
<span class="line"><span>global.SetValue(AscendC::GetBlockIdx(), AscendC::GetBlockIdx());</span></span>
<span class="line"><span>// 算子中多核操作虽然不在同一个地址，但在同一个Cache Line, 会出现数据的随机覆盖，和通用CPU的行为不同</span></span>
<span class="line"><span>// 调用DataCacheCleanAndInvalid指令后，由于多核操作的时间不一致，最终结果存在随机性，后执行的核会覆盖前面核的结果</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;uint64_t, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT&gt;(global);</span></span>
<span class="line"><span>// 示例4：ENTIRE_DATA_CACHE 模式，假设mmAddr_为0x20（非64B对齐）</span></span>
<span class="line"><span>// 本样例仅做示例说明，便于开发者理解使用限制，非正常使用样例</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;uint64_t&gt; global;</span></span>
<span class="line"><span>global.SetGlobalBuffer((__gm__ uint64_t*)mmAddr_ + AscendC::GetBlockIdx() * 1024);</span></span>
<span class="line"><span>for( int i = 0; i &lt; 8; i++) {</span></span>
<span class="line"><span>   global.SetValue(i, AscendC::GetBlockIdx());</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 刷新整个Data Cache，性能较差</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;uint64_t, AscendC::CacheLine::ENTIRE_DATA_CACHE, AscendC::DcciDst::CACHELINE_OUT&gt;(global);</span></span></code></pre></div>`,23)])])}const _=n(d,[["render",i]]);export{A as __pageData,_ as default};
